def _drop_unnamed_fk(table: str, column: str) -> None:
    """删除 MySQL **自动命名**的外键（2026-10-10 修复迁移回滚）。

    autogenerate 会把外键名写成 None（见本文件 upgrade 的
    ``op.create_foreign_key(None, ...)``），而 MySQL 方言要求显式名字——
    ``op.drop_constraint(None, ...)`` 会在 ``format_constraint`` 处抛
    AssertionError，使整条 downgrade 链在此中断。
    MySQL 生成的名字（如 ``xxx_ibfk_1``）与创建顺序相关、不可硬编码，
    故从 information_schema 反查真实约束名。
    """
    name = op.get_bind().execute(
        sa.text(
            "SELECT CONSTRAINT_NAME FROM information_schema.KEY_COLUMN_USAGE "
            "WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = :t "
            "AND COLUMN_NAME = :c AND REFERENCED_TABLE_NAME IS NOT NULL LIMIT 1"
        ),
        {"t": table, "c": column},
    ).scalar()
    if name:
        op.drop_constraint(name, table, type_="foreignkey")


